"""Select first committed bank before derived quality scoring; no new samples."""
from pathlib import Path
import json,hashlib,datetime
import numpy as np
OUT=Path('results/thrml_spw/boolean_classifier_cached_reuse');PARENT=Path('results/thrml_spw/boolean_classifier')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    assert not (OUT/'protocol.json').exists();blob=(PARENT/'manifest.json').read_bytes();m=json.loads(blob);p=json.loads((PARENT/'protocol.json').read_text());prep=json.loads(Path('results/thrml_spw/boolean_classifier_preparation_v2/preparation.json').read_text());rows=[r for r in m['rows'] if r['regime']=='R1'];assert len(rows)==150
    for path,h in p['critical_sources'].items():assert sha(path)==h
    counts0=np.empty((5,3,10,64,32),np.uint16);counts1=np.empty((5,3,10,32,10),np.uint16);selected=[];subset_updates=0
    for row in rows:
        assert sha(row['path'])==row['sha256'];raw=np.load(row['path']);i,j,k=row['model'],p['samples']['R1'].index(row['T']),row['seed'];counts0[i,j,k]=raw['weight_0'][0];counts1[i,j,k]=raw['weight_1'][0];assert counts0[i,j,k].max()<=row['T'] and counts1[i,j,k].max()<=row['T'];selected.append({'model':i,'budget_index':j,'T':row['T'],'seed':k,'parent_name':row['name'],'parent_path':row['path'],'parent_sha256':row['sha256'],'selected_bank':0});subset_updates+=2368*row['T']
    assert subset_updates==243667200;np.savez_compressed(OUT/'selected_counts.npz',weight_0=counts0,weight_1=counts1);(OUT/'parent_manifest_capture.json').write_bytes(blob)
    result={'stage':'derived_static_cache_control_selected_before_quality_scoring','recorded_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_sha256':sha(__file__),'parent_protocol_sha256':sha(PARENT/'protocol.json'),'parent_manifest_capture_sha256':sha(OUT/'parent_manifest_capture.json'),'selected_counts_sha256':sha(OUT/'selected_counts.npz'),'selected':selected,'selection':'Bank0 from every one of all150 native R1 cases, fixed before examining derived quality; no favorable seed/bank search. Weight-only unary fields/count observer do not depend on activations, so both sampled layers are reusable.','new_native_updates':0,'native_updates_in_selected_existing_subset':subset_updates,'original_executed_parent_R1_updates':304584000000,'total_executed_parent_updates_unchanged':True,'counterfactual_cache_policy':'One sampled weight estimate per layer/model/seed/budget is retained in F64 and used for all10000 already-consumed test images. Shared programming may be amortized; reconstructed float cache/readout remain conventional arithmetic.','counterfactual_sampling_reduction_for_full_dataset':1250,'additional_F64_reconstructed_weight_cache_bits':2368*64,'additional_F64_reconstructed_weight_cache_bytes':2368*8,'FP32_cache_not_evaluated':'A smaller F32 cache would change arithmetic/rounding and is not silently substituted.','quality_gate':'Derived quality scoring waits for parent complete native replay AND parent statistical audit; this is a separate reuse control, not a replacement of the sealed original R1/R3 comparison.','statistical_note':'Cached and per-bank R1 have the same marginal sampled-weight law per input, so expected dataset-average accuracy/loss agree by linearity. Finite-run variance differs because cached perturbations are shared across all images. Derived estimates reuse parent MC seeds; they are not independent replications.','scope':'Static sampled-weight retention is distinct from merely retaining a bias command. Lower sampling from caching is conditional on retaining full reconstructed weights and conventional neural arithmetic; no one-p-bit-only memory, physical energy or latency advantage is established.'}
    (OUT/'protocol.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k in ['stage','new_native_updates','native_updates_in_selected_existing_subset','additional_F64_reconstructed_weight_cache_bytes']}))
if __name__=='__main__':main()
